fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let q=e.path();if e.file_type().unwrap().is_dir(){let n=e.file_name();let n=n.to_string_lossy();if !n.starts_with("target-")&&n!="frozen"{walk(&q,out)}}else if e.file_type().unwrap().is_file(){out.push(q)}}}
fn seal(){let d=Path::new(D);let mut paths=vec![];walk(d,&mut paths);paths.sort();let mut pins=BTreeMap::new();for p in paths{let rel=p.strip_prefix(d).unwrap().display().to_string();if ["SHA256SUMS","artifact-index.json"].contains(&rel.as_str()){continue}pins.insert(rel,hash(p));}save(d.join("artifact-index.json"),&json!(pins));pins.insert("artifact-index.json".into(),hash(d.join("artifact-index.json")));fs::write(d.join("SHA256SUMS"),pins.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();println!("Sealed {} hashes",pins.len());}
